insert into public.businesses(name,category,city,address,phone,website,description,status,verified,claimed,rating,review_count,source,source_url,verification_source,verified_at) values('Iron Zone Gym','Health & Wellness','Mountain House','579 Wicklund Crossing Way, Mountain House, CA 95391','(209) 207-9281','https://www.ironzonegym.com/','Mountain House gym advertising strength equipment, coaching support and 24/7 access for members. Member access is not the same as staffed or visitor hours. Confirm membership, day-pass arrangements and training availability directly.','approved',true,false,null,0,'editorial_first_party','https://www.ironzonegym.com/contact','first_party_website_desk_check',now()) returning id into bid;
insert into public.listing_checks(business_id,source_url,checked_fields,service_areas,service_tags,scope_note) values(bid,'https://www.ironzonegym.com/contact',array['identity','website','public phone','address','advertised services'],array['Mountain House'],array['gym','strength training'],'MH Matters printed page29 lead independently checked against official home/contact pages November8. 24/7 describes members access only; staffed/visitor hours and holiday access not established. No credential, safety, quality, pricing or appointment endorsement. No photos reused.');
insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference) values(bid,'{}'::jsonb,'{"name": "Iron Zone Gym", "phone": "(209) 207-9281", "website": "https://www.ironzonegym.com/", "contact": "https://www.ironzonegym.com/contact", "address": "579 Wicklund Crossing Way, Mountain House, CA 95391", "description": "Mountain House gym advertising strength equipment, coaching support and 24/7 access for members. Member access is not the same as staffed or visitor hours. Confirm membership, day-pass arrangements and training availability directly."}'::jsonb,'Newspaper lead independently checked against first-party site','https://www.ironzonegym.com/contact');end $curate$;
insert into public.events(title,description,city,location,start_date,end_date,category,source_url,confidence,status,source,confidence_score,needs_review,ingestion_status) select 'Preschool Storytime with Tracy Animal Services','No animals will be present. Preschoolers can hear stories with a City of Tracy Animal Services officer and learn about their work. Official Mountain House library occurrence checked November 8, 2026; confirm attendance arrangements with the library.','Mountain House','Mountain House Branch Library, 201 E Main Street, Mountain House, CA 95391','2026-11-19T11:30:00-08:00','2026-11-19T12:15:00-08:00','Community programs','https://www.ssjcpl.org/events-services/events-calendar/mountain-house/preschool-storytime-with-tracy-animal-services?id=1795116600-246956','HIGH','approved','editorial_community_2026',0.95,false,'approved' where not exists(select 1 from public.events where city='Mountain House' and title='Preschool Storytime with Tracy Animal Services' and start_date='2026-11-19T11:30:00-08:00'::timestamptz);
insert into public.events(title,description,city,location,start_date,end_date,category,source_url,confidence,status,source,confidence_score,needs_review,ingestion_status) select 'Winter Reading Kickoff: Snow Party!','Snow-themed games, activities and music at the Mountain House library, ahead of the winter reading challenge beginning December 1. All-ages November 30 occurrence checked against the official library page November 8, 2026. Confirm attendance arrangements with the library; no promise of real snow.','Mountain House','Mountain House Branch Library, 201 E Main Street, Mountain House, CA 95391','2026-11-30T16:00:00-08:00','2026-11-30T17:00:00-08:00','Community programs','https://www.ssjcpl.org/events-services/events-calendar/mountain-house/winter-reading-kickoff-snow-party?id=1796083200-242216','HIGH','approved','editorial_seasonal_2026',0.95,false,'approved' where not exists(select 1 from public.events where city='Mountain House' and title='Winter Reading Kickoff: Snow Party!' and start_date='2026-11-30T16:00:00-08:00'::timestamptz);
